                        "<div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'JuKD6k7nDwfO0Ckv'})\">Instinct de géant</div>",
                        "<div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'k7M9jedvt31AJ5ZR'})\">Instinct de la furie</div>",
                        "<div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'VDot7CDcXElxmkkz'})\">Instinct du dragon</div>",
